std::optional<nlohmann::json> read_json(const fs::path& file)
{
    std::ifstream stream(file);
    if (!stream)
        return std::nullopt;
    nlohmann::json json = nlohmann::json::parse(stream, nullptr, false);
    if (json.is_discarded() || !json.is_object())
