                <button className="primary" onClick={() => onRetry(message.id)}>Retry</button>
              )}
            </div>
          )}
          {message.state === 'stopped' && (
            <div className="message-failure">
              <div className="meta">Stopped before it finished.</div>
              {message.id === lastReplyId && !readOnly && (
                <button className="primary" onClick={() => onRetry(message.id)}>Retry</button>
              )}
            </div>
          )}
        </div>
      </div>
    );
  };
  // The printer panel's cards for one message's calls, 8 under its bubble.
  const activityCards = (message: Message) =>
              <span className="agent-key-keeps">Keeps <code>{hint}</code> until the new key passes</span>
            )}
          </div>
        </div>
      )}

      {form === 'closed' && standing === 'sessionOnly' && (
        <p className="agent-row-note">
          You’ll need to add it again after JusPrin restarts.
        </p>
      )}
      {form === 'closed' && standing === 'rejected' && (
        <p className="agent-row-note">Replace it with a working key, or remove it.</p>

