// What the Import from OrcaSlicer window says on each of its screens, and
// which shell_action each of its buttons asks for.

import { describe, expect, it, vi } from 'vitest';
import { render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import type { OrcaImportPayload } from '../bridge/protocol';
import { OrcaImport } from './OrcaImport';

const folder = '~/Library/Application Support/OrcaSlicer';

function actions() {
  return { importPrinters: vi.fn(), chooseFolder: vi.fn(), close: vi.fn() };
}

function state(overrides: Partial<OrcaImportPayload>): OrcaImportPayload {
  return { kind: 'orca_import', screen: 'found', folder, error: '', ...overrides };
}

describe('the Import from OrcaSlicer window', () => {
  it('offers the printers JusPrin does not have and marks the ones it does', async () => {
    const act = actions();
    render(<OrcaImport actions={act} state={state({
      printers: [{ name: 'Bambu Lab P1S 0.4 nozzle', already: false }, { name: 'Prusa MK4 0.4 nozzle', already: false },
        { name: 'Bambu Lab A1 mini 0.4 nozzle', already: true }],
      newPrinters: 2, newFilaments: 14,
    })} />);
    expect(screen.getByText(/JusPrin found 2 printers in OrcaSlicer that it doesn’t have yet/)).toBeInTheDocument();
    const rows = within(screen.getByRole('list', { name: 'OrcaSlicer printers' })).getAllByRole('listitem');
    expect(rows.map((row) => row.textContent)).toEqual([
      'Bambu Lab P1S 0.4 nozzle', 'Prusa MK4 0.4 nozzle', 'Bambu Lab A1 mini 0.4 nozzleAlready in JusPrin',
    ]);
    expect(screen.getByText(folder)).toBeInTheDocument();

    // Each new printer has a tick box, ticked; the button counts the ticked ones.
    expect(screen.getAllByRole('checkbox')).toHaveLength(2);
    await userEvent.click(screen.getByRole('checkbox', { name: 'Prusa MK4 0.4 nozzle' }));
    expect(screen.getByRole('button', { name: 'Import 1 printer' })).toBeEnabled();
    await userEvent.click(screen.getByRole('checkbox', { name: 'Bambu Lab P1S 0.4 nozzle' }));
    expect(screen.getByRole('button', { name: 'Import' })).toBeDisabled();
    await userEvent.click(screen.getByRole('checkbox', { name: 'Bambu Lab P1S 0.4 nozzle' }));

    await userEvent.click(screen.getByRole('button', { name: 'Choose another folder…' }));
    expect(act.chooseFolder).toHaveBeenCalledTimes(1);
    await userEvent.click(screen.getByRole('button', { name: 'Import 1 printer' }));
    // The import holds the app, so the window says it is working on it, and
    // asks only once that has been painted.
    expect(screen.getByRole('button', { name: 'Importing…' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Cancel' })).toBeDisabled();
    expect(screen.queryByRole('button', { name: 'Choose another folder…' })).toBeNull();
    expect(act.importPrinters).not.toHaveBeenCalled();
    await waitFor(() => expect(act.importPrinters).toHaveBeenCalledTimes(1));
    expect(act.importPrinters).toHaveBeenCalledWith(['Bambu Lab P1S 0.4 nozzle']);
  });

  it('says one printer in the singular', () => {
    render(<OrcaImport actions={actions()} state={state({ printers: [{ name: 'Voron', already: false }], newPrinters: 1 })} />);
    expect(screen.getByText(/JusPrin found 1 printer in OrcaSlicer that it doesn’t have yet\. JusPrin copies it with its filaments/))
      .toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Import 1 printer' })).toBeInTheDocument();
  });

  it('offers new filaments and settings when every printer is already in JusPrin', () => {
    render(<OrcaImport actions={actions()} state={state({ printers: [{ name: 'Voron', already: true }], newPrinters: 0, newFilaments: 2 })} />);
    expect(screen.getByText(/JusPrin found filaments or settings in OrcaSlicer/)).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Import' })).toBeInTheDocument();
  });

  it('says there is nothing new, with only a way to another folder and Close', async () => {
    const act = actions();
    render(<OrcaImport actions={act} state={state({ screen: 'nothing_new', printers: [{ name: 'Voron', already: true }] })} />);
    expect(screen.getByText('Every printer in this OrcaSlicer folder is already in JusPrin, so there is nothing to import.')).toBeInTheDocument();
    expect(screen.getByText('Already in JusPrin')).toBeInTheDocument();
    expect(screen.getAllByRole('button').map((button) => button.textContent)).toEqual(['Choose another folder…', 'Close']);
    await userEvent.click(screen.getByRole('button', { name: 'Close' }));
    expect(act.close).toHaveBeenCalledTimes(1);
  });

  it('says where it looked when there is no folder, and asks for one', async () => {
    const act = actions();
    render(<OrcaImport actions={act} state={state({ screen: 'no_folder' })} />);
    expect(screen.getByText(/JusPrin didn’t find OrcaSlicer’s folder on this computer/)).toBeInTheDocument();
    expect(screen.getByText(`Looked in ${folder}`)).toBeInTheDocument();
    await userEvent.click(screen.getByRole('button', { name: 'Choose the folder…' }));
    expect(act.chooseFolder).toHaveBeenCalledTimes(1);
  });

  it('says a folder had no printers, and shows a refused pick', () => {
    render(<OrcaImport actions={actions()}
      state={state({ screen: 'no_printers', error: 'JusPrin found no OrcaSlicer printers in that folder.' })} />);
    expect(screen.getByText(/JusPrin found no OrcaSlicer printers in this folder/)).toBeInTheDocument();
    expect(screen.getByRole('alert')).toHaveTextContent('JusPrin found no OrcaSlicer printers in that folder.');
  });

  it('lists what became of each, with the filaments as a count, and keeps the project printer', async () => {
    const act = actions();
    render(<OrcaImport actions={act} state={state({
      screen: 'imported',
      result: [
        { kind: 'printer', name: 'Bambu Lab P1S 0.4 nozzle', renamedTo: '', imported: true, reason: '' },
        { kind: 'printer', name: 'Shop X1C', renamedTo: 'Shop X1C (Orca copy)', imported: true, reason: '' },
        { kind: 'process', name: 'Old', renamedTo: '', imported: false, reason: 'Not imported. The file has no version.' },
        { kind: 'filament', name: 'PLA', renamedTo: '', imported: true, reason: '' },
        { kind: 'filament', name: 'PETG', renamedTo: '', imported: true, reason: '' },
      ],
    })} />);
    expect(screen.getByText('The 2 imported printers are now in the printer menu at the top of the window. '
      + 'The open project still uses the same printer as before. OrcaSlicer’s own files were not changed.')).toBeInTheDocument();
    const rows = within(screen.getByRole('list', { name: 'Imported' })).getAllByRole('listitem');
    expect(rows.map((row) => row.textContent)).toEqual([
      'Bambu Lab P1S 0.4 nozzleImported', 'Shop X1CImported as ‘Shop X1C (Orca copy)’', 'OldNot imported. The file has no version.',
    ]);
    expect(screen.getByText('2 filaments imported: PLA, PETG.')).toBeInTheDocument();
    await userEvent.click(screen.getByRole('button', { name: 'Done' }));
    expect(act.close).toHaveBeenCalledTimes(1);
  });

  it('names a single imported printer by the name the menu shows', () => {
    render(<OrcaImport actions={actions()} state={state({ screen: 'imported', result: [
      { kind: 'printer', name: 'Voron 2.4 350', renamedTo: 'Voron 2.4 350 (Orca copy)', imported: true, reason: '' },
      { kind: 'printer', name: 'Old', renamedTo: '', imported: false, reason: 'Not imported. The file has no version.' },
    ] })} />);
    expect(screen.getByText('Voron 2.4 350 (Orca copy) is now in the printer menu at the top of the window. '
      + 'The open project still uses the same printer as before. OrcaSlicer’s own files were not changed.')).toBeInTheDocument();
  });

  it('says how to try again on the line itself, with Done as the only button', () => {
    render(<OrcaImport actions={actions()} state={state({ screen: 'imported', result: [
      { kind: 'printer', name: 'Old', renamedTo: '', imported: false, reason: 'JusPrin couldn’t read this file. To try again, choose File › Import › Import from OrcaSlicer…' },
    ] })} />);
    expect(screen.getByText('Old').closest('li')).toHaveTextContent('JusPrin couldn’t read this file. To try again, choose File › Import › Import from OrcaSlicer…');
    expect(screen.getAllByRole('button').map((button) => button.textContent)).toEqual(['Done']);
  });
});

// File › Import › Import from OrcaSlicer…: the printers an OrcaSlicer folder
// has, the ones JusPrin already has marked and skipped, and once imported,
// what became of each (canvas "JusPrin v2", boards orca-import-02 found,
// 03 imported, 04 nothing new, 05 no folder). The window's title bar carries
// the title; the host finds the folder and does the importing.

import { useEffect, useState } from 'react';
import type { OrcaImportLine, OrcaImportPayload } from '../bridge/protocol';
import { afterPaint } from '@shared/afterPaint';
import { OrcaImportResultLines, OrcaPrinterList } from './OrcaImportLists';

export interface OrcaImportActions {
  // The printers left ticked, by name.
  importPrinters: (printers: string[]) => void;
  chooseFolder: () => void;
  close: () => void;
}

const plural = (count: number, one: string, many: string) => `${count} ${count === 1 ? one : many}`;

function Folder({ path, looked, onChoose }: { path: string; looked?: boolean; onChoose?: () => void }) {
  return (
    <div className="orca-import-folder">
      <span className="jp-icon jp-icon-monitor" aria-hidden="true" />
      <span className="orca-import-folder-path">{looked ? `Looked in ${path}` : path}</span>
      {onChoose && <button type="button" className="link" onClick={onChoose}>Choose another folder…</button>}
    </div>
  );
}

// Board 03: the same lines as board 17 on the first launch. One printer is
// named as the menu shows it; several are counted, since the list below names
// each. The page isn't told the open project's printer, so it says only that
// the printer stayed.
function Result({ result }: { result: OrcaImportLine[] }) {
  const printers = result.filter((line) => line.kind === 'printer' && line.imported);
  const where = 'in the printer menu at the top of the window. ';
  return <>
    <p className="orca-import-lead">
      {printers.length === 1 && `${printers[0].renamedTo || printers[0].name} is now ${where}`}
      {printers.length > 1 && `The ${printers.length} imported printers are now ${where}`}
      The open project still uses the same printer as before. OrcaSlicer’s own files were not changed.
    </p>
    <OrcaImportResultLines lines={result} />
  </>;
}

export function OrcaImport({ state, actions }: { state: OrcaImportPayload; actions: OrcaImportActions }) {
  // Importing holds the app for a while; the buttons say so meanwhile.
  // The host answers with the next screen once it is done.
  const [busy, setBusy] = useState(false);
  useEffect(() => setBusy(false), [state]);
  // Every printer JusPrin doesn't have yet starts ticked.
  const fresh = (state.printers ?? []).filter((printer) => !printer.already).map((printer) => printer.name);
  const [chosen, setChosen] = useState(fresh);
  // A new list, as after choosing another folder, starts over; the same one pushed again does not.
  const listed = fresh.join('\n');
  useEffect(() => setChosen(fresh), [listed]);
  const choose = (name: string, ticked: boolean) =>
    setChosen((now) => (ticked ? [...now, name] : now.filter((one) => one !== name)));
  const run = (action: () => void) => {
    setBusy(true);
    afterPaint(action);
  };
  const folder = state.folder ?? '';
  const newPrinters = state.newPrinters ?? 0;

  let body;
  let buttons;
  switch (state.screen) {
    case 'imported':
      body = <Result result={state.result ?? []} />;
      buttons = <button type="button" className="primary" onClick={actions.close}>Done</button>;
      break;
    case 'nothing_new':
      body = <>
        <p className="orca-import-lead">Every printer in this OrcaSlicer folder is already in JusPrin, so there is nothing to import.</p>
        <OrcaPrinterList printers={state.printers ?? []} />
        <Folder path={folder} onChoose={actions.chooseFolder} />
      </>;
      buttons = <button type="button" className="primary" onClick={actions.close}>Close</button>;
      break;
    case 'no_folder':
    case 'no_printers':
      body = <>
        <p className="orca-import-lead">
          {state.screen === 'no_folder'
            ? 'JusPrin didn’t find OrcaSlicer’s folder on this computer. '
            : 'JusPrin found no OrcaSlicer printers in this folder. '}
          If OrcaSlicer keeps its settings somewhere else, choose that folder.
        </p>
        <Folder path={folder} looked />
      </>;
      buttons = <>
        <button type="button" onClick={actions.close}>Cancel</button>
        <button type="button" className="primary" onClick={actions.chooseFolder}>Choose the folder…</button>
      </>;
      break;
    case 'found':
      body = <>
        <p className="orca-import-lead">
          {newPrinters > 0
            ? `JusPrin found ${plural(newPrinters, 'printer', 'printers')} in OrcaSlicer that it doesn’t have yet. JusPrin copies ${newPrinters === 1 ? 'it' : 'them'} with ${newPrinters === 1 ? 'its' : 'their'} filaments, settings and printer connections. `
            : 'JusPrin found filaments or settings in OrcaSlicer that it doesn’t have yet. JusPrin copies them. '}
          OrcaSlicer keeps its own copy.
        </p>
        <OrcaPrinterList printers={state.printers ?? []} chosen={chosen} onChoose={choose} disabled={busy} />
        <Folder path={folder} onChoose={busy ? undefined : actions.chooseFolder} />
      </>;
      buttons = <>
        <button type="button" disabled={busy} onClick={actions.close}>Cancel</button>
        <button type="button" className="primary" disabled={busy || (newPrinters > 0 && chosen.length === 0)}
          onClick={() => run(() => actions.importPrinters(chosen))}>
          {busy ? 'Importing…' : chosen.length > 0 ? `Import ${plural(chosen.length, 'printer', 'printers')}` : 'Import'}
        </button>
      </>;
      break;
  }

  return (
    <div className="orca-import" data-testid="orca-import">
      <div className="orca-import-content">
        {body}
        {state.error && <p className="orca-import-error" role="alert">{state.error}</p>}
      </div>
      <div className="orca-import-buttons">{buttons}</div>
    </div>
  );
}

